from pathlib import Path
import json,hashlib
R=Path(__file__).parent;P=json.load(open(R/'C2_selected_parameters.json'));W=json.load(open(R/'drape_width_screen.json'));vis={k:json.load(open(R/f'{k}_branch_visibility.json')) for k in ['D','C2','C3']}
def summary(v):
 a=[abs(t) for t in v];return {'count':len(a),'mean_abs_px':sum(a)/len(a) if a else None,'max_abs_px':max(a) if a else None}
out={'status':'PARTIAL_COMPONENT_DIAGNOSTIC_NOT_SOURCE_ACCEPTANCE','camera_rule':'G/H/F frozen D cameras; no external calibration. N640 source-relative static-window/background rotation/focal hypothesis; no furniture fitting. Same geometry in all views.','safety_gates':{'exact_source_identity':'native file SHA and 1920x1080 verified','named_model_parts':'two actual cushion meshes and gray mesh; rounded transition points excluded from straight branch fit','model_visibility':'whole-scene actual camera ray cast 2px inside projected boundary','image_registration':'none'},'sofa_left':{},'sofa_right':{},'gray_outer_right':{},'excluded':{'rounded_shoulders':[{'branch_id':b['branch_id'],'points':b['excluded_rounded_transition_samples']} for b in P['branches'] if b['excluded_rounded_transition_samples']],'old_gray_samples':W['excluded_legacy_samples'],'N640_model_occlusions':[t for t in vis['C3']['tests'] if not t['expected_visible']]},'limits':['No aggregate whole-image accuracy or model acceptance score.','No claim that material vertex identities are shared across source frames.','Column depth/gray left visibility remain visibly wrong; C2 and C3 overall source review fails.','N640 pure rotation/focal hypothesis cannot prove a fixed patient eye or exclude translation.','Source H gray y900 is hidden by right sofa arm; G gray y100 is a distinct top-end branch that model does not match; neither is silently counted as long visible right edge.']}
for k in ['G','H','N640']:
 for obj,key in [('Sofa • reclined back cushion 1','sofa_left'),('Sofa • reclined back cushion 2','sofa_right')]:
  bad={tuple(t['source']) for t in vis['C3']['tests'] if t['view']==k and t['expected_object']==obj and not t['expected_visible']}
  bb=[t['residual'] for b in P['branches'] if b['frame']==k and b['mesh']==obj for t in b['before'] if t['residual'] is not None and tuple(t['source']) not in bad];aa=[t['residual'] for b in P['branches'] if b['frame']==k and b['mesh']==obj for t in b['after'] if t['residual'] is not None and tuple(t['source']) not in bad]
  out[key][k]={'D':summary(bb),'C3':summary(aa),'role':'conditional_holdout' if k=='N640' else 'fit'}
for k,z in W['views'].items():out['gray_outer_right'][k]={mode:summary([t['residual'] for t in vals]) for mode,vals in z.items()};out['gray_outer_right'][k]['role']='conditional_fixed_camera_holdout' if k=='F' else 'fit'
(R/'source_diagnostic_summary.json').write_text(json.dumps(out,ensure_ascii=False,indent=2));print(json.dumps({k:out[k] for k in ['sofa_left','sofa_right','gray_outer_right']},indent=2))
